// All artwork lives in sprites.json as data URIs (generated by tools/pack.cjs),
// so the app is a single self-contained bundle and never depends on binary files.
import sprites from "./sprites.json";

const S = sprites as unknown as {
  doll: string;
  head: string;
  neck: string;
  hand: string;
  room: string;
  places: string[];
  items: Record<string, string>;
};

export const itemSrc = (id: string): string => S.items[id] ?? "";

export const IMG = {
  doll: S.doll,
  head: S.head,
  neck: S.neck,
  hand: S.hand,
  room: S.room,
  places: {
    cafe: S.places[0],
    beach: S.places[1],
    night: S.places[2],
    park: S.places[3],
    pool: S.places[4],
    gala: S.places[5],
    snow: S.places[6],
  },
};
